const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function guidedPrintKit(g){
 const c=g.runtime,find=id=>g.objects.find(o=>o.id===id),page=(title,body)=>`<article class="kit-page guided-kit"><div class="eyebrow">BOARD STUDIO · ${esc(g.name)}</div><h1>${title}</h1>${body}<footer>Print at 100% · Prototype for playtesting</footer></article>`;
 const cellLabel=i=>[...c.boats.map((b,n)=>b.cell===i?`Boat ${n+1} · ${b.value} points`:null),...c.pawnIds.map((id,p)=>c.starts[p]===i?`${c.playerNames[p]} starts`:null)].filter(Boolean).map(esc).join('<br>');
 const grid=`<div class="paper-grid" style="grid-template-columns:repeat(${c.columns},1fr)">${c.spaceIds.map((id,i)=>`<div><small>${i+1} · ${esc(find(id).name)}</small><b>${c.kind==='routing'?'↑→↓←'[c.directions[i]]:''}</b><span>${c.kind==='routing'?(i===c.starts[0]?'INLET':''):cellLabel(i)}</span></div>`).join('')}</div>`;
 let out=page('Build your table',`<p>2 players · ${c.kind==='routing'?'Rotate and route':'Move and rescue'}</p><ol><li>Print on Letter or A4 at actual size (100%). Measure the calibration line below. Use opaque paper or cardstock.</li><li>${c.kind==='routing'?'Keep the board page intact. Cut the separate gutter tiles and place them over the matching numbered cells, arrows pointing as shown.':'Keep the board page intact. Cut the tokens and place boats and keepers on the starting cells shown.'}</li><li>Cut tokens along the dashed edges. Optional: glue them to thin card before cutting. ${c.kind==='rescue'?'Cut the weather fronts and identical backs. Glue each front to a back, or use opaque card sleeves; never reveal the next weather.':'Set Water and Lock beside the board. Have a pencil and paper for scores and completed turns.'}</li><li>Use the named north and south edges as scoring areas, or put the lighthouse tokens beside the board. Read the quick reference, then the full rules. Start at zero points.</li></ol><h2>Check the scale</h2><div class="calibration">1 inch / 25.4 mm</div><h2>Included</h2><p>${c.spaceIds.length} board spaces${c.kind==='routing'?` + ${c.spaceIds.length} separate gutter tiles`:''}; ${g.objects.filter(o=>o.type==='piece').length} tokens/landmarks; ${c.events.length} weather cards. Supplies: scissors, optional glue/cardstock${c.kind==='routing'?', pencil and score paper':''}.</p><p>Digital 3D landmarks become flat labeled tokens. This kit requires no 3D printer.</p>`);
 out+=page('Board & starting positions',`<p class="paper-compass">NORTH · ${esc(c.playerNames[0])}</p>${grid}<p class="paper-compass">SOUTH · ${esc(c.playerNames[1])}</p><p>${c.kind==='routing'?'Tile numbers identify positions. Rotate tiles in place; the inlet always stays at position '+(c.starts[0]+1)+'.':'Move only between edge-adjacent cells. Diagonal movement costs two steps. Pawns may share spaces.'}</p>`);
 if(c.kind==='routing')for(let i=0;i<c.spaceIds.length;i+=12)out+=page('Cut the gutter tiles',`<p>Cut dashed edges; place on matching cells. Arrow points north at the top of the page.</p><div class="gutter-cut-grid" style="--tile-size:${Math.min(1.7,6/c.columns)}in">${c.spaceIds.slice(i,i+12).map((id,j)=>`<div class="gutter-cut"><small>${i+j+1}</small><b>${'↑→↓←'[c.directions[i+j]]}</b><span>${c.starts[0]===i+j?'INLET':''}</span></div>`).join('')}</div>`);
 const pieces=g.objects.filter(o=>o.type==='piece');for(let i=0;i<pieces.length;i+=12)out+=page('Tokens & scoring areas',`<div class="paper-tokens">${pieces.slice(i,i+12).map(o=>{const b=c.boats.findIndex(b=>b.id===o.id);return `<div style="border-top-color:${o.color}"><strong>${esc(o.name)}</strong>${b>=0?`<span>Boat ${b+1}<br>${c.boats[b].value} points</span>`:''}</div>`;}).join('')}</div><p>Cut the dashed outlines. Keep rescued and sunk pieces in separate areas. Text identifies pieces even in grayscale.</p>`);
 const events=c.events.map(e=>find(e.id));for(let i=0;i<events.length;i+=4){out+=page('Weather fronts',`<div class="weather-print">${events.slice(i,i+4).map(o=>`<div><h2>${esc(o.name)}</h2><p>${esc(o.text)}</p></div>`).join('')}</div>`);out+=page('Matching weather backs',`<p>Single-sided printing: cut and glue a back to each front. Keep all backs identical.</p><div class="weather-print">${events.slice(i,i+4).map(()=>`<div class="weather-back"><h2>${esc(g.name)}</h2><p>WEATHER</p></div>`).join('')}</div>`);}
 out+=page('Quick reference',`<h2>${c.kind==='routing'?'One turn':'One round'}</h2><ol>${(c.kind==='routing'?['Choose any gutter except the one under Lock.','Rotate it exactly 90° left or right; move Lock onto it.','Trace water from the inlet until it exits or revisits a tile.','North exit: first player +1. South exit: second player +1. Side or loop: zero.','Count the turn. After '+c.turnLimit+' turns, compare points; ties share victory.']:['Reveal weather and resolve sinking before anyone acts.','First keeper takes one action: move OR rescue OR pass.','Other keeper takes one action. Moving does not rescue.','Discard weather; alternate which keeper goes first next round.','End when all boats leave the board or the last round finishes. Compare points, then boat counts.']).map(t=>`<li>${t}</li>`).join('')}</ol><p>Try one practice round together. Explain the action and score out loud. Reset, then begin. Afterward, swap seats and record confusing rules or repetitive choices.</p>`);
 for(const [key,text] of Object.entries(g.rules))out+=page('Rules · '+esc(key),`<p>${esc(text)}</p>`);
 return out;
}
